Adds a straight connector with ShapeCollection.AddConnector and sets its LineFormat's Width, DashStyle, CapStyle, BeginArrowheadStyle and EndArrowheadStyle, round-trips the presentation through a MemoryStream, and checks each of the five values on the reloaded line.

Example:
// Authored example: style a connector's line with a dash pattern and arrowheads at both ends
using Aspose.Slides.Foss;
using Aspose.Slides.Foss.Drawing;
using Aspose.Slides.Foss.Export;

using var presentation = new Presentation();
IConnector connector = presentation.Slides[0].Shapes!.AddConnector(ShapeType.StraightConnector1, 50, 50, 150, 0);

connector.LineFormat.Width = 3.0f;
connector.LineFormat.DashStyle = LineDashStyle.Dash;
connector.LineFormat.CapStyle = LineCapStyle.Round;
connector.LineFormat.BeginArrowheadStyle = LineArrowheadStyle.Oval;
connector.LineFormat.EndArrowheadStyle = LineArrowheadStyle.Triangle;

using var buffer = new MemoryStream();
presentation.Save(buffer, SaveFormat.Pptx);
buffer.Position = 0;

using var reopened = new Presentation(buffer);
var reloadedLine = reopened.Slides[0].Shapes![0].LineFormat;

Console.WriteLine("width: " + reloadedLine.Width);
Console.WriteLine("dash style: " + reloadedLine.DashStyle);
Console.WriteLine("cap style: " + reloadedLine.CapStyle);
Console.WriteLine("begin arrow: " + reloadedLine.BeginArrowheadStyle);
Console.WriteLine("end arrow: " + reloadedLine.EndArrowheadStyle);

if (Math.Abs(reloadedLine.Width - 3.0f) > 0.01)
{
    throw new Exception("line width mismatch");
}
if (reloadedLine.DashStyle != LineDashStyle.Dash)
{
    throw new Exception("dash style mismatch");
}
if (reloadedLine.BeginArrowheadStyle != LineArrowheadStyle.Oval)
{
    throw new Exception("begin arrowhead mismatch");
}
if (reloadedLine.EndArrowheadStyle != LineArrowheadStyle.Triangle)
{
    throw new Exception("end arrowhead mismatch");
}
