Creates a one-shape presentation and sets its FillFormat.FillType to Gradient, then sets the GradientFormat's LinearGradientAngle and adds two colour stops with GradientStopCollection.Add, round-trips the presentation through a MemoryStream with Presentation.Save and the Presentation(Stream) constructor, and checks the reloaded fill type, stop count and angle.

Example:
// Authored example: build a linear gradient fill with two colour stops and read it back
using Aspose.Slides.Foss;
using Aspose.Slides.Foss.Drawing;
using Aspose.Slides.Foss.Export;

using var presentation = new Presentation();
IAutoShape shape = presentation.Slides[0].Shapes!.AddAutoShape(ShapeType.Rectangle, 50, 50, 300, 120);

shape.FillFormat.FillType = FillType.Gradient;
IGradientFormat gradient = shape.FillFormat.GradientFormat;
gradient.LinearGradientAngle = 45f;
gradient.GradientStops.Add(0.0f, Color.FromArgb(255, 0, 112, 192));
gradient.GradientStops.Add(1.0f, Color.White);

using var buffer = new MemoryStream();
presentation.Save(buffer, SaveFormat.Pptx);
buffer.Position = 0;

using var reopened = new Presentation(buffer);
IFillFormat reloadedFill = reopened.Slides[0].Shapes![0].FillFormat;
IGradientFormat reloadedGradient = reloadedFill.GradientFormat;

Console.WriteLine("fill type: " + reloadedFill.FillType);
Console.WriteLine("stop count: " + reloadedGradient.GradientStops.Count);
Console.WriteLine("angle: " + reloadedGradient.LinearGradientAngle);

if (reloadedFill.FillType != FillType.Gradient)
{
    throw new Exception("expected a gradient fill");
}
if (reloadedGradient.GradientStops.Count != 2)
{
    throw new Exception("expected exactly two gradient stops");
}
if (Math.Abs(reloadedGradient.LinearGradientAngle - 45f) > 0.5f)
{
    throw new Exception("gradient angle mismatch");
}
