Adds two rectangles and a connector, binds the connector's StartShapeConnectedTo and EndShapeConnectedTo with explicit StartShapeConnectionSiteIndex/EndShapeConnectionSiteIndex values, moves it to the front with ShapeCollection.Reorder, round-trips the presentation through a MemoryStream, and checks the reloaded shape count and both connection site indices.

Example:
// Authored example: bind a connector between two shapes by connection site and reorder shapes
using Aspose.Slides.Foss;
using Aspose.Slides.Foss.Drawing;
using Aspose.Slides.Foss.Export;

using var presentation = new Presentation();
IShapeCollection shapes = presentation.Slides[0].Shapes!;
IAutoShape first = shapes.AddAutoShape(ShapeType.Rectangle, 50, 50, 100, 60);
IAutoShape second = shapes.AddAutoShape(ShapeType.Rectangle, 250, 50, 100, 60);
IConnector connector = shapes.AddConnector(ShapeType.StraightConnector1, 150, 80, 100, 0);

connector.StartShapeConnectedTo = first;
connector.StartShapeConnectionSiteIndex = 2;
connector.EndShapeConnectedTo = second;
connector.EndShapeConnectionSiteIndex = 0;

shapes.Reorder(0, connector);

using var buffer = new MemoryStream();
presentation.Save(buffer, SaveFormat.Pptx);
buffer.Position = 0;

using var reopened = new Presentation(buffer);
IShapeCollection reloadedShapes = reopened.Slides[0].Shapes!;
var reloadedConnector = (IConnector)reloadedShapes[0];

Console.WriteLine("shape count: " + reloadedShapes.Count);
Console.WriteLine("start site: " + reloadedConnector.StartShapeConnectionSiteIndex);
Console.WriteLine("end site: " + reloadedConnector.EndShapeConnectionSiteIndex);

if (reloadedShapes.Count != 3)
{
    throw new Exception("expected exactly three shapes");
}
